import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileAccess {
    public String readFile(String filename) {
        // Define the base directory as an absolute path to prevent path traversal.
        Path basePath = Paths.get("/var/data").toAbsolutePath().normalize();

        // Construct the target path by resolving the user input against the base path.
        // This ensures the final path cannot escape the intended directory.
        Path targetPath = basePath.resolve(filename).normalize();

        // Verify that the resolved path still starts with the base directory.
        if (!targetPath.startsWith(basePath)) {
            throw new SecurityException("Invalid file path detected.");
        }

        return "Reading: " + targetPath.toString();
    }
}
